insert into public.suppliers (id, name, country, moq_meters, verified, data) values
  ('sup-lariana', 'Lariana Seterie', 'IT', 50, true, '{"id":"sup-lariana","name":"Lariana Seterie","country":"IT","city":"Como","type":"mill","specialties":[{"en":"Silk satins & crepes","ar":"ساتان وكريب الحرير"},{"en":"Wool crepe & coatings","ar":"كريب ومعاطف الصوف"},{"en":"Digital printing","ar":"الطباعة الرقمية"}],"moqMeters":50,"leadTimeDays":28,"certifications":["OEKO-TEX 100","ISO 9001"],"founded":1952,"rating":4.9,"description":{"en":"Third-generation silk mill on Lake Como producing charmeuse, crepe de chine and fine wool crepes for couture houses.","ar":"مصنع حرير من الجيل الثالث على بحيرة كومو، ينتج الشارموز وكريب دي شين وكريب الصوف الفاخر لدور الأزياء الراقية."}}'::jsonb),
