  ('sup-kyoto', 'Kamo Orimono', 'JP', 100, true, '{"id":"sup-kyoto","name":"Kamo Orimono","country":"JP","city":"Kyoto","type":"converter","specialties":[{"en":"Jacquard & brocade","ar":"الجاكار والبروكار"},{"en":"Nida & abaya crepes","ar":"كريب النِّدا والعبايات"},{"en":"Hemp & technical blends","ar":"القنب والمخاليط التقنية"}],"moqMeters":100,"leadTimeDays":45,"certifications":["bluesign","OEKO-TEX 100"],"founded":1931,"rating":4.8,"description":{"en":"Kyoto converter pairing Nishijin-style jacquard looms with modern high-twist polyester crepes favoured for abayas.","ar":"شركة تحويل في كيوتو تجمع بين أنوال الجاكار التقليدية وأقمشة الكريب عالية البرم المفضلة للعبايات."}}'::jsonb),
  ('sup-highland', 'Highland Weavers', 'GB', 60, true, '{"id":"sup-highland","name":"Highland Weavers","country":"GB","city":"Galashiels","type":"mill","specialties":[{"en":"Wool tweed","ar":"تويد الصوف"},{"en":"Worsted gabardine","ar":"جبردين الصوف المسرّح"},{"en":"Woollen coatings","ar":"أقمشة المعاطف الصوفية"}],"moqMeters":60,"leadTimeDays":40,"certifications":["Woolmark","RWS"],"founded":1898,"rating":4.8,"description":{"en":"Scottish Borders mill weaving tweeds and worsted suitings from responsibly sourced wool.","ar":"مصنع في الحدود الاسكتلندية ينسج التويد وأقمشة البدلات من صوف مسؤول المصدر."}}'::jsonb)
